//! Operator knowledge for `copybook explain`.
//!
//! DO NOT EDIT. Source: `docs/reference/ERROR_CODES.md`.
//! Regenerate: `cargo run -p xtask -- explain sync-knowledge`.
//! Freshness is enforced by `docs verify-all` (`explain-knowledge`).

/// One operator knowledge row: what a stable error means and how to fix it.
pub struct Explanation {
    /// Full stable error identity (e.g. `CBKE501_JSON_TYPE_MISMATCH`).
    pub code: &'static str,
    /// Severity verbatim from the error-code reference.
    pub severity: &'static str,
    /// What the error means, verbatim from the reference.
    pub description: &'static str,
    /// Diagnostic context the error carries, verbatim.
    pub context: &'static str,
    /// Operator remediation, verbatim from the reference.
    pub resolution: &'static str,
}

