/// Look up operator knowledge by full code (`CBKE501_JSON_TYPE_MISMATCH`)
/// or short code (`CBKE501`). Returns `None` for unknown identities.
#[inline]
#[must_use]
pub fn explanation_for(code: &str) -> Option<&'static Explanation> {
    let upper = code.trim().to_ascii_uppercase();
    let short = upper.split('_').next().unwrap_or(&upper);
    EXPLANATIONS
        .iter()
        .find(|row| row.code == upper || row.code.split('_').next().unwrap_or(row.code) == short)
}
